SPEC = {'before': 'c54671ae1a2ce8771c39ba3ac43243e92e7de9885ff9f4b9dbb886d37210aeb2', 'expected': {'_extract_positions_chunk': 'async def _extract_positions_chunk(document_text: str) -> TenderMultiExtractionResult:\n    document_text = _complete_document_text(document_text)\n    schema_hint = TenderMultiExtractionResult.model_json_schema()\n    user_prompt = f"""Извлеки фактические товарные позиции из этого фрагмента. Если есть только общие условия, название закупки, образец незаполненной формы или упоминание товара без конкретной спецификации, верни positions: []. Не придумывай позиции по заголовку. Номера лотов и позиций бери из спецификации.\nJSON-схема:\\n{schema_hint}\\n\\nДокументы:\\n---\\n{document_text}\\n---\\nОтветь только JSON."""\n    from pydantic import ValidationError\n    import json\n    base_prompt = user_prompt\n    for attempt in range(2):\n        response = await llm_router.complete(\n            task=TaskType.EXTRACT_FIELDS,\n            system_prompt=MULTI_EXTRACTION_SYSTEM_PROMPT,\n            user_prompt=user_prompt,\n            max_tokens=6000,\n            temperature=0.0,\n            json_mode=True,\n        )\n        try:\n            return TenderMultiExtractionResult.model_validate(response.as_json())\n        except ValidationError as exc:\n            if attempt:\n                raise\n            issues = [{\'path\': \'.\'.join(map(str, e[\'loc\'])), \'type\': e[\'type\']}\n                      for e in exc.errors(include_input=False, include_url=False)]\n            user_prompt = base_prompt + (\n                "\\nПредыдущий ответ не прошёл проверку схемы: "\n                + json.dumps(issues, ensure_ascii=False)\n                + "\\nИзвлеки позиции заново из исходного фрагмента. "\n                "value — одно скалярное значение или null; raw_quote — строка или null. "\n                "Не объединяй изделия разных размеров в одну позицию. "\n                "Если в спецификации несколько строк, сохрани каждую с её номером, "\n                "размерами, единицей и количеством. Не распределяй общий объём "\n                "между размерами, если распределение не указано. "\n                "Альтернативные размеры одного изделия не превращай в новые позиции: "\n                "оставь value=null и исходное требование в raw_quote."\n            )\n', '_document_chunks': 'def _document_chunks(text: str, limit: int = 24000) -> list[str]:\n    """Lossless split, preferring document boundaries and then whole lines."""\n    _complete_document_text(text)\n    import re\n    if len(text) <= limit:\n        return [text]\n    sections = re.split(r"(?=\\n\\n### DOCUMENT:)", text)\n    chunks = []\n    for section in sections:\n        while len(section) > limit:\n            cut = section.rfind("\\n", 0, limit + 1)\n            if cut < limit // 2:\n                cut = limit\n            else:\n                cut += 1\n            chunks.append(section[:cut])\n            section = section[cut:]\n        if section:\n            chunks.append(section)\n    return chunks\n', '_merge_extractions': 'def _merge_extractions(results):\n    """Merge complementary evidence; retain fail-closed handling of real conflicts."""\n    import re\n    from decimal import Decimal, InvalidOperation\n\n    def canonical(value):\n        if value is None or not str(value).strip():\n            return None\n        value = re.sub(r\'\\s+\', \' \', str(value)).strip().casefold()\n        if re.fullmatch(r\'[+-]?\\d+(?:[.,]\\d+)?\', value):\n            try:\n                return (\'number\', Decimal(value.replace(\',\', \'.\')))\n            except InvalidOperation:\n                pass\n        return (\'text\', value)\n\n    # Only the observed generic foil heading, with no position-specific facts.\n    # Never discard an unnumbered/unknown product just because mass is absent.\n    def foil_heading(pos):\n        name = re.sub(r\'\\s+\', \' \', pos.product_name.value or \'\').strip().casefold()\n        if not re.fullmatch(r\'фольг[аи] алюминиев(?:ая|ой) с нанесенной печатью\', name):\n            return False\n        specifics = (\'quantity\', \'mass_kg\', \'unit\', \'alloy\', \'temper\',\n                     \'thickness_mm\', \'width_mm\', \'length_mm\', \'diameter_mm\',\n                     \'machining\', \'has_drawings\')\n        return not any(canonical(getattr(pos, f).value) is not None\n                       or getattr(pos, f).raw_quote for f in specifics)\n\n    numbered = {}\n    partial = []\n    for result in results:\n        if canonical(result.partial_delivery_allowed.value) is not None:\n            partial.append(result.partial_delivery_allowed)\n        for pos in result.positions:\n            identity = (pos.lot_number or \'1\', pos.position_number)\n            numbered.setdefault(identity, []).append(pos)\n\n    merged = []\n    for identity, variants in numbered.items():\n        # A concrete foil line at the SAME identity must be present before the\n        # generic procurement heading can be omitted. Retained in snapshots.\n        concrete_foil = any(\n            not foil_heading(p)\n            and re.match(r\'^фольга\\s+алюминиевая\\b\', (p.product_name.value or \'\').strip(), re.I)\n            and any(canonical(getattr(p, f).value) is not None\n                    for f in (\'quantity\', \'mass_kg\', \'width_mm\', \'thickness_mm\'))\n            for p in variants\n        )\n        if concrete_foil:\n            variants = [p for p in variants if not foil_heading(p)]\n        combined = variants[0].model_copy(deep=True)\n        for pos in variants[1:]:\n            for field in type(pos).model_fields:\n                if field in (\'position_number\', \'lot_number\'):\n                    continue\n                old, new = getattr(combined, field), getattr(pos, field)\n                left, right = canonical(old.value), canonical(new.value)\n                if left is not None and right is not None and left != right:\n                    raise ValueError(\'EXTRACTION_POSITION_CONFLICT: differing fragments for lot/position \'\n                                     + str(identity) + \'; field=\' + field\n                                     + \'; review required; no result saved\')\n                if left is None and right is not None:\n                    # A null carrying a quote can be an intentionally unresolved\n                    # range/requirement, not a missing value. Do not override it.\n                    if old.raw_quote and old.raw_quote != new.raw_quote:\n                        raise ValueError(\'EXTRACTION_POSITION_CONFLICT: unresolved quoted field \'\n                                         + str(identity) + \'; field=\' + field)\n                    setattr(combined, field, new.model_copy(deep=True))\n                elif left is not None and right is None:\n                    if new.raw_quote and new.raw_quote != old.raw_quote:\n                        raise ValueError(\'EXTRACTION_POSITION_CONFLICT: unresolved quoted field \'\n                                         + str(identity) + \'; field=\' + field)\n                elif left == right:\n                    quotes = list(dict.fromkeys(q for q in (old.raw_quote, new.raw_quote) if q))\n                    setattr(combined, field, ExtractedField(\n                        value=old.value, raw_quote=\'\\n\'.join(quotes) or None,\n                        confidence=min(old.confidence, new.confidence),\n                    ))\n        merged.append(combined)\n\n    if len({canonical(f.value) for f in partial}) > 1:\n        raise ValueError(\'EXTRACTION_PARTIAL_DELIVERY_CONFLICT: review required\')\n    if not merged:\n        raise ValueError(\'EXTRACTION_NO_SPECIFICATION_POSITIONS: no result saved\')\n    return TenderMultiExtractionResult(\n        positions=merged,\n        partial_delivery_allowed=partial[0] if partial else ExtractedField(),\n    )\n', 'extract_tender_positions': "async def extract_tender_positions(document_text: str) -> TenderMultiExtractionResult:\n    from pathlib import Path\n    import hashlib, tempfile\n    from app.core.config import settings\n    chunks = _document_chunks(document_text)\n    # Persist each validated response before normalization/merge can reject it.\n    root = Path(settings.storage_path) / 'extraction_snapshots'\n    root.mkdir(parents=True, exist_ok=True)\n    digest = hashlib.sha256(document_text.encode()).hexdigest()\n    run = Path(tempfile.mkdtemp(prefix=digest[:16]+'-', dir=root))\n    snapshot = {'input_sha256': digest, 'chunk_count': len(chunks),\n                'state': 'running', 'responses': []}\n    path = run / 'responses.json'\n    _save_extraction_snapshot(path, snapshot)\n    results = []\n    try:\n        for index, chunk in enumerate(chunks):\n            response = await _extract_positions_chunk(chunk)\n            snapshot['responses'].append({'chunk_index': index,\n                'chunk_sha256': hashlib.sha256(chunk.encode()).hexdigest(),\n                'result': response.model_dump(mode='json')})\n            _save_extraction_snapshot(path, snapshot)\n            results.append(_normalize_extraction(response, document_text))\n        merged = _merge_extractions(results)\n        snapshot['state'] = 'completed'\n        _save_extraction_snapshot(path, snapshot)\n        return merged\n    except Exception as exc:\n        snapshot['state'] = 'failed'\n        snapshot['error_type'] = type(exc).__name__\n        snapshot['error'] = str(exc)\n        _save_extraction_snapshot(path, snapshot)\n        raise\n"}, 'replacement': {'_extract_positions_chunk': 'async def _extract_positions_chunk(document_text: str) -> TenderMultiExtractionResult:\n    from app.llm.reliable_extraction import extract_chunk\n    return await extract_chunk(document_text, globals())\n', 'extract_tender_positions': 'async def extract_tender_positions(document_text: str) -> TenderMultiExtractionResult:\n    from app.llm.reliable_extraction import extract_all\n    return await extract_all(document_text, globals())\n'}}
HELPER = '"""Bounded structured extraction with private raw evidence and validated checkpoints."""\nimport hashlib\nimport json\nimport os\nimport tempfile\nfrom contextvars import ContextVar\nfrom pathlib import Path\nfrom pydantic import ValidationError\n\nVERSION = \'llm-reliable-20261019-v1\'\n_context = ContextVar(\'extraction_evidence\', default=None)\n\ndef digest(value):\n    return hashlib.sha256(value.encode()).hexdigest()\n\ndef write(path, value):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    fd, tmp = tempfile.mkstemp(dir=path.parent)\n    try:\n        with os.fdopen(fd, \'w\', encoding=\'utf-8\') as f:\n            json.dump(value, f, ensure_ascii=False, default=str)\n        os.replace(tmp, path)\n    finally:\n        if os.path.exists(tmp): os.unlink(tmp)\n\ndef finish_reason(response):\n    raw = response.raw\n    if isinstance(raw, dict):\n        alternatives = (raw.get(\'result\') or {}).get(\'alternatives\') or []\n        return alternatives[0].get(\'status\') if alternatives else None\n    return getattr(raw, \'stop_reason\', None)\n\nasync def extract_chunk(text, ns):\n    text = ns[\'_complete_document_text\'](text)\n    model = ns[\'TenderMultiExtractionResult\']\n    schema = json.dumps(model.model_json_schema(), ensure_ascii=False)\n    base = (\n        \'Извлеки только фактические строки спецификации. Общие условия, заголовок, \'\n        \'пустые формы: positions=[]. Номера лотов и позиций только из источника. \'\n        \'Не объединяй разные изделия и размеры в одну позицию. value — скаляр \'\n        \'или null; raw_quote — точная короткая цитата строкой или null. \'\n        \'Не распределяй общий объём по размерам самостоятельно. Альтернативные \'\n        \'размеры одной позиции: value=null, требование в raw_quote. \'\n        \'Не повторяй общий текст договора в каждой позиции.\\nСхема:\\n\' + schema\n        + \'\\nИсходный фрагмент:\\n\' + text\n    )\n    prompt = base\n    for attempt in range(2):\n        response = await ns[\'llm_router\'].complete(\n            task=ns[\'TaskType\'].EXTRACT_FIELDS,\n            system_prompt=ns[\'MULTI_EXTRACTION_SYSTEM_PROMPT\'],\n            user_prompt=prompt, max_tokens=6000, temperature=0.0, json_mode=True,\n        )\n        reason = finish_reason(response)\n        context = _context.get()\n        evidence = {\n            \'provider\': response.provider, \'model\': response.model,\n            \'finish_reason\': reason, \'attempt\': attempt + 1,\n            \'text\': response.text,\n        }\n        # Persist before decoding; do not persist provider headers or credentials.\n        if context:\n            run, index = context\n            evidence_path = run / f\'chunk-{index:04d}-attempt-{attempt+1}.json\'\n            write(evidence_path, evidence)\n        try:\n            if reason in {\'max_tokens\', \'ALTERNATIVE_STATUS_TRUNCATED\'}:\n                raise ValueError(\'LLM_RESPONSE_TRUNCATED\')\n            result = model.model_validate(response.as_json())\n        except (ValueError, ValidationError) as exc:\n            if context:\n                evidence[\'error_type\'] = type(exc).__name__\n                evidence[\'error\'] = str(exc)\n                write(evidence_path, evidence)\n            if attempt:\n                raise ValueError(\'EXTRACTION_RESPONSE_INVALID_AFTER_RETRY: \' + str(exc)) from exc\n            if isinstance(exc, ValidationError):\n                issues = [{\'path\': list(e[\'loc\']), \'type\': e[\'type\']}\n                          for e in exc.errors(include_input=False, include_url=False)]\n                hint = json.dumps(issues, ensure_ascii=False)\n            else:\n                hint = \'Невалидный или незавершённый JSON. Проверь кавычки и запятые.\'\n            prompt = base + \'\\nПовторная попытка: \' + hint + (\n                \'\\nИзвлеки заново из источника. Верни компактный полный JSON, \'\n                \'короткие цитаты. Не добавляй объяснения. Не теряй строки спецификации.\'\n            )\n        else:\n            return result\n\nasync def extract_all(text, ns):\n    from app.core.config import settings\n    chunks = ns[\'_document_chunks\'](text, limit=8000)\n    root = Path(settings.storage_path) / \'extraction_snapshots\'\n    root.mkdir(parents=True, exist_ok=True)\n    run = Path(tempfile.mkdtemp(prefix=digest(text)[:16]+\'-\', dir=root))\n    route = ns[\'llm_router\']._resolve_route(ns[\'TaskType\'].EXTRACT_FIELDS)\n    # Invalidate checkpoints for changed model, schema, prompts or extraction code.\n    fingerprint = digest(json.dumps({\n        \'version\': VERSION, \'input\': digest(text), \'route\': route,\n        \'schema\': ns[\'TenderMultiExtractionResult\'].model_json_schema(),\n        \'prompt\': ns[\'MULTI_EXTRACTION_SYSTEM_PROMPT\'],\n        \'code\': digest(Path(ns[\'__file__\']).read_text()),\n    }, sort_keys=True, ensure_ascii=False))\n    cache = root / \'_validated_cache\' / fingerprint\n    state = {\'input_sha256\': digest(text), \'version\': VERSION,\n             \'chunk_count\': len(chunks), \'state\': \'running\', \'responses\': []}\n    path = run / \'responses.json\'\n    write(path, state)\n    results = []\n    try:\n        for index, chunk in enumerate(chunks):\n            key = cache / (str(index) + \'-\' + digest(chunk) + \'.json\')\n            result = None\n            if key.exists():\n                try:\n                    result = ns[\'TenderMultiExtractionResult\'].model_validate(\n                        json.loads(key.read_text(encoding=\'utf-8\')))\n                except (ValueError, OSError):\n                    result = None\n            cached = result is not None\n            if not cached:\n                token = _context.set((run, index))\n                try:\n                    result = await extract_chunk(chunk, ns)\n                finally:\n                    _context.reset(token)\n                write(key, result.model_dump(mode=\'json\'))\n            state[\'responses\'].append({\'chunk_index\': index, \'chunk_sha256\': digest(chunk),\n                                      \'cached\': cached, \'result\': result.model_dump(mode=\'json\')})\n            write(path, state)\n            results.append(ns[\'_normalize_extraction\'](result, text))\n        merged = ns[\'_merge_extractions\'](results)\n        state[\'state\'] = \'completed\'\n        write(path, state)\n        return merged\n    except Exception as exc:\n        state.update(state=\'failed\', error_type=type(exc).__name__, error=str(exc))\n        write(path, state)\n        raise\n'
TESTS = 'import asyncio, json, tempfile\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import patch\nfrom app.llm import reliable_extraction as r\nfrom app.llm import extraction as e\nfrom app.llm.router import LLMResponse\n\nasync def main():\n    ns = dict(vars(e))\n    calls=[]\n    responses=[]\n    async def complete(**kwargs):\n        calls.append(kwargs)\n        item=responses.pop(0)\n        if isinstance(item, Exception): raise item\n        return item\n    router=SimpleNamespace(complete=complete, _resolve_route=lambda task: (\'test\',\'test\'))\n    ns[\'llm_router\']=router\n    empty=json.dumps({\'positions\':[]})\n    def response(text=empty, stop=None):\n        return LLMResponse(text,\'test\',\'test\',SimpleNamespace(stop_reason=stop))\n    responses.extend([response(\'{\'),response()])\n    await r.extract_chunk(\'Документ\', ns)\n    assert len(calls)==2\n    responses.extend([response(empty,\'max_tokens\'),response()])\n    await r.extract_chunk(\'Документ\', ns)\n    assert len(calls)==4\n    responses.extend([response(\'{\'),response(\'{\')])\n    try: await r.extract_chunk(\'Документ\',ns)\n    except ValueError as exc: assert \'AFTER_RETRY\' in str(exc)\n    else: raise AssertionError(\'invalid response accepted\')\n    assert len(calls)==6\n    responses.extend([response(\'{"positions":[{"width_mm":{"value":["130","181"]}}]}\'),response()])\n    await r.extract_chunk(\'Документ\', ns)\n    assert len(calls)==8\n    with tempfile.TemporaryDirectory() as tmp:\n        with patch(\'app.core.config.settings\',SimpleNamespace(storage_path=tmp)):\n            ns[\'_document_chunks\']=lambda text,limit: [\'первый\',\'второй\']\n            ns[\'_normalize_extraction\']=lambda result,text: result\n            ns[\'_merge_extractions\']=lambda results: results\n            responses.extend([response(),TimeoutError(\'test\')])\n            try: await r.extract_all(\'полный документ\',ns)\n            except TimeoutError: pass\n            else: raise AssertionError(\'transport failure swallowed\')\n            before=len(calls)\n            responses.append(response())\n            await r.extract_all(\'полный документ\',ns)\n            assert len(calls)==before+1, \'checkpoint not reused\'\n            raw=list(Path(tmp).glob(\'extraction_snapshots/*/chunk-*.json\'))\n            assert raw and \'text\' in json.loads(raw[0].read_text())\n            before=len(calls)\n            def conflict(results): raise ValueError(\'EXTRACTION_POSITION_CONFLICT\')\n            ns[\'_merge_extractions\']=conflict\n            try: await r.extract_all(\'полный документ\',ns)\n            except ValueError as exc: assert \'POSITION_CONFLICT\' in str(exc)\n            else: raise AssertionError(\'conflict suppressed\')\n            assert len(calls)==before\n    assert not responses\n    print(\'LLM_RECOVERY_TESTS_OK: JSON retry, schema retry, truncation, bounded failure, checkpoints, transport propagation, conflict preservation, raw evidence\')\nasyncio.run(main())\n'
import argparse, ast, hashlib, json, os, shutil, subprocess, tempfile
from pathlib import Path

def replace_functions(text):
    lines=text.splitlines(keepends=True)
    nodes={n.name:n for n in ast.parse(text).body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
    for name, code in SPEC['replacement'].items():
        node=nodes[name]
        actual=''.join(lines[node.lineno-1:node.end_lineno]).strip()
        if actual != SPEC['expected'][name].strip():
            raise SystemExit('FUNCTION_VERSION_CONFLICT: '+name)
    for name in sorted(SPEC['replacement'],key=lambda name:nodes[name].lineno,reverse=True):
        node=nodes[name]
        lines[node.lineno-1:node.end_lineno]=[SPEC['replacement'][name]]
    result=''.join(lines)
    compile(result,'extraction.py','exec')
    return result

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--files-only',action='store_true')
    args=parser.parse_args()
    root=Path.cwd()
    path=root/'app/llm/extraction.py'
    helper=root/'app/llm/reliable_extraction.py'
    if not path.is_file(): raise SystemExit('Run from tender-ai-platform-v6.2 root')
    old=path.read_text()
    nodes={n.name:ast.get_source_segment(old,n).strip() for n in ast.parse(old).body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
    installed=all(nodes.get(name)==value.strip() for name,value in SPEC['replacement'].items())
    if installed:
        if not helper.exists() or helper.read_text()!=HELPER:
            raise SystemExit('HELPER_VERSION_CONFLICT; no changes')
        changes={}
    else:
        if hashlib.sha256(path.read_bytes()).hexdigest()!=SPEC['before']:
            raise SystemExit('VERSION_CONFLICT: app/llm/extraction.py; no changes')
        if helper.exists(): raise SystemExit('Unexpected existing helper; no changes')
        changes={path:replace_functions(old),helper:HELPER}
    for p,text in changes.items(): compile(text,str(p),'exec')
    print('COMPATIBLE; FILES_TO_UPDATE:',len(changes),flush=True)
    if args.check:return
    if changes:
        backup=Path(tempfile.mkdtemp(prefix='llm-recovery-backup-',dir=root.parent))
        originals={p:p.read_bytes() if p.exists() else None for p in changes}
        for p,raw in originals.items():
            if raw is not None:
                target=backup/p.relative_to(root)
                target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(raw)
        (backup/'manifest.json').write_text(json.dumps({str(p.relative_to(root)):raw is not None for p,raw in originals.items()}))
        print('BACKUP:',backup,flush=True)
        try:
            for p,text in changes.items():
                fd,tmp=tempfile.mkstemp(dir=p.parent)
                with os.fdopen(fd,'w') as f:f.write(text)
                os.chmod(tmp,p.stat().st_mode & 0o777 if p.exists() else 0o644)
                os.replace(tmp,p)
        except Exception:
            for p,raw in originals.items():
                if raw is None:p.unlink(missing_ok=True)
                else:p.write_bytes(raw)
            raise
    if args.files_only:
        print('FILES_ONLY; containers not updated');return
    subprocess.run(['docker','compose','build','app','celery_worker','celery_discovery'],check=True)
    subprocess.run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input=TESTS,text=True,check=True)
    ids=subprocess.check_output(['docker','compose','ps','-q','celery_worker','celery_discovery'],text=True).split()
    if ids:
        print('Warm shutdown: waiting for active tasks, without forced termination.',flush=True)
        subprocess.run(['docker','kill','--signal=SIGTERM',*ids],check=True)
        subprocess.run(['docker','wait',*ids],check=True)
    subprocess.run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery'],check=True)
    print('LLM_RESPONSE_RECOVERY_INSTALLED',flush=True)
    print('PIPELINE_HEALTH: read-only; no manual collection or analysis',flush=True)
    audit=subprocess.run(['docker','compose','exec','-T','celery_discovery','python','-m','app.sources.pipeline_health'])
    if audit.returncode:raise SystemExit('INSTALLED_BUT_HEALTH_AUDIT_FAILED')
    print('No DB edits, task submissions, queue purges or notifications. Schedules retained.',flush=True)

if __name__=='__main__':main()
